import sys
HEAD='''//! Guard-page harness for the aocl-blas trait methods with explicit layout / leading dimension / increment (`Scalar`, `RealScalar`,
//! `ComplexScalar`; f64 and Complex64). GENERATED by tools/gen-blas-trait-harness.py (do not edit); 0 of the 259 cases faulted before any fix. Every vector is strided (`inc` = 2) and every
//! matrix has a padded leading dimension (`minor + 1`), in both layouts; the CONTROL passes exactly `(n - 1) * inc + 1` / `(major - 1) * ld + minor`
//! elements, each short case passes ONE buffer one element short at the end of a committed page before a PAGE_NOACCESS page (a fault = HOLE).
//! One process per test (tools/safe-api-harness.py). Windows only; Linux unmeasured.
#![cfg(windows)]
#![allow(unused_parens, unused_mut, unused_variables, reason = "generated: size expressions are parenthesised, not every call mutates every buffer or uses the layout")]
use aocl_blas::*;
use core::ffi::c_void;

extern "system" {
    fn VirtualAlloc(addr: *mut c_void, size: usize, ty: u32, prot: u32) -> *mut c_void;
    fn VirtualProtect(addr: *mut c_void, size: usize, prot: u32, old: *mut u32) -> i32;
    fn VirtualFree(addr: *mut c_void, size: usize, ty: u32) -> i32;
}
const PAGE: usize = 4096;
fn at_guard<T: Copy, R>(init: &[T], n: usize, f: impl FnOnce(&mut [T]) -> R) -> R {
    assert!(n <= init.len() && n * core::mem::size_of::<T>() <= PAGE);
    unsafe {
        let base = VirtualAlloc(core::ptr::null_mut(), 2 * PAGE, 0x3000, 0x04);
        assert!(!base.is_null());
        let mut old = 0u32;
        assert_ne!(VirtualProtect((base as *mut u8).add(PAGE) as *mut c_void, PAGE, 0x01, &mut old), 0);
        let start = (base as *mut u8).add(PAGE - n * core::mem::size_of::<T>()) as *mut T;
        for (i, v) in init.iter().take(n).enumerate() {
            start.add(i).write(*v);
        }
        let r = f(core::slice::from_raw_parts_mut(start, n));
        VirtualFree(base, 0, 0x8000);
        r
    }
}
const M: usize = 3;
const N: usize = 4;
const K: usize = 2;
const KL: usize = 1;
const KU: usize = 1;
/// elements a strided vector of `n` entries needs
fn v(n: usize, inc: usize) -> usize {
    (n - 1) * inc + 1
}
/// leading dimension and element count of a padded `rows x cols` matrix in `l`
fn m(l: Layout, rows: usize, cols: usize) -> (usize, usize) {
    let (major, minor) = if l == Layout::RowMajor { (rows, cols) } else { (cols, rows) };
    (minor + 1, (major - 1) * (minor + 1) + minor)
}
/// band storage (rows, cols) for `k` off-diagonals: `n x (k + 1)` row-major, `(k + 1) x n` column-major
fn bd(l: Layout, k: usize) -> (usize, usize) {
    if l == Layout::RowMajor { (N, k + 1) } else { (k + 1, N) }
}
fn p(n: usize) -> usize {
    n * (n + 1) / 2
}
'''
# spec: (name, scalar-type-key, [slice (key, mut, ty-size-expr)], call template using {key} for slices; dims in text; uses `l` layout)
R="f64"; C="Complex64"
def band_dims(k): return f"bd(l, {k})"
specs=[]
def S(name,ty,trait,slices,call,layout=True):
    specs.append((name,ty,trait,slices,call,layout))
# level 1 (two-vector forms: n from x, y must hold (n-1)*incy+1)
for nm,ex in (("copy","<f64 as Scalar>::copy({x}, 2, {y}, 2)"),("swap","<f64 as Scalar>::swap({x}, 2, {y}, 2)"),("axpy","<f64 as Scalar>::axpy(2.0, {x}, 2, {y}, 2)"),("dot","<f64 as Scalar>::dot({x}, 2, {y}, 2).map(|_| ())"),("rot","<f64 as RealScalar>::rot({x}, 2, {y}, 2, 0.6, 0.8)")):
    mutx = nm in ("swap","rot")
    S(nm,R,"Scalar",[("x","v(N, 2)",mutx),("y","v(N, 2)",True if nm!="dot" else False)],ex,layout=False)
# level 2
S("gemv",R,"Scalar",[("a","m(l, M, N).1",False),("x","v(N, 2)",False),("y","v(M, 2)",True)],"<f64 as Scalar>::gemv(l, Trans::No, M, N, 1.0, {a}, m(l, M, N).0, {x}, 2, 0.5, {y}, 2)")
S("trmv",R,"Scalar",[("a","m(l, N, N).1",False),("x","v(N, 2)",True)],"<f64 as Scalar>::trmv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, {a}, m(l, N, N).0, {x}, 2)")
S("trsv",R,"Scalar",[("a","m(l, N, N).1",False),("x","v(N, 2)",True)],"<f64 as Scalar>::trsv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, {a}, m(l, N, N).0, {x}, 2)")
S("gemm",R,"Scalar",[("a","m(l, M, K).1",False),("b","m(l, K, N).1",False),("c","m(l, M, N).1",True)],"<f64 as Scalar>::gemm(l, Trans::No, Trans::No, M, N, K, 1.0, {a}, m(l, M, K).0, {b}, m(l, K, N).0, 0.5, {c}, m(l, M, N).0)")
S("symm",R,"Scalar",[("a","m(l, M, M).1",False),("b","m(l, M, N).1",False),("c","m(l, M, N).1",True)],"<f64 as Scalar>::symm(l, Side::Left, Uplo::Upper, M, N, 1.0, {a}, m(l, M, M).0, {b}, m(l, M, N).0, 0.5, {c}, m(l, M, N).0)")
S("syrk",R,"Scalar",[("a","m(l, N, K).1",False),("c","m(l, N, N).1",True)],"<f64 as Scalar>::syrk(l, Uplo::Upper, Trans::No, N, K, 1.0, {a}, m(l, N, K).0, 0.5, {c}, m(l, N, N).0)")
S("syr2k",R,"Scalar",[("a","m(l, N, K).1",False),("b","m(l, N, K).1",False),("c","m(l, N, N).1",True)],"<f64 as Scalar>::syr2k(l, Uplo::Upper, Trans::No, N, K, 1.0, {a}, m(l, N, K).0, {b}, m(l, N, K).0, 0.5, {c}, m(l, N, N).0)")
bd=lambda k:band_dims(k)
S("gbmv",R,"Scalar",[("a",f"m(l, {bd('(KL + KU)')}.0, {bd('(KL + KU)')}.1).1",False),("x","v(N, 2)",False),("y","v(M, 2)",True)],f"<f64 as Scalar>::gbmv(l, Trans::No, M, N, KL, KU, 1.0, {{a}}, m(l, {bd('(KL + KU)')}.0, {bd('(KL + KU)')}.1).0, {{x}}, 2, 0.5, {{y}}, 2)")
S("tbmv",R,"Scalar",[("a",f"m(l, {bd('K')}.0, {bd('K')}.1).0 * N",False),("x","v(N, 2)",True)],f"<f64 as Scalar>::tbmv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, K, {{a}}, m(l, {bd('K')}.0, {bd('K')}.1).0, {{x}}, 2)")
S("tbsv",R,"Scalar",[("a",f"m(l, {bd('K')}.0, {bd('K')}.1).0 * N",False),("x","v(N, 2)",True)],f"<f64 as Scalar>::tbsv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, K, {{a}}, m(l, {bd('K')}.0, {bd('K')}.1).0, {{x}}, 2)")
S("tpmv",R,"Scalar",[("ap","p(N)",False),("x","v(N, 2)",True)],"<f64 as Scalar>::tpmv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, {ap}, {x}, 2)")
S("tpsv",R,"Scalar",[("ap","p(N)",False),("x","v(N, 2)",True)],"<f64 as Scalar>::tpsv(l, Uplo::Upper, Trans::No, Diag::NonUnit, N, {ap}, {x}, 2)")
S("trmm",R,"Scalar",[("a","m(l, M, M).1",False),("b","m(l, M, N).1",True)],"<f64 as Scalar>::trmm(l, Side::Left, Uplo::Upper, Trans::No, Diag::NonUnit, M, N, 1.0, {a}, m(l, M, M).0, {b}, m(l, M, N).0)")
S("trsm",R,"Scalar",[("a","m(l, M, M).1",False),("b","m(l, M, N).1",True)],"<f64 as Scalar>::trsm(l, Side::Left, Uplo::Upper, Trans::No, Diag::NonUnit, M, N, 1.0, {a}, m(l, M, M).0, {b}, m(l, M, N).0)")
S("symv",R,"RealScalar",[("a","m(l, N, N).1",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],"<f64 as RealScalar>::symv(l, Uplo::Upper, N, 1.0, {a}, m(l, N, N).0, {x}, 2, 0.5, {y}, 2)")
S("syr",R,"RealScalar",[("x","v(N, 2)",False),("a","m(l, N, N).1",True)],"<f64 as RealScalar>::syr(l, Uplo::Upper, N, 1.0, {x}, 2, {a}, m(l, N, N).0)")
S("syr2",R,"RealScalar",[("x","v(N, 2)",False),("y","v(N, 2)",False),("a","m(l, N, N).1",True)],"<f64 as RealScalar>::syr2(l, Uplo::Upper, N, 1.0, {x}, 2, {y}, 2, {a}, m(l, N, N).0)")
S("ger",R,"RealScalar",[("x","v(M, 2)",False),("y","v(N, 2)",False),("a","m(l, M, N).1",True)],"<f64 as RealScalar>::ger(l, M, N, 1.0, {x}, 2, {y}, 2, {a}, m(l, M, N).0)")
S("sbmv",R,"RealScalar",[("a",f"m(l, {bd('K')}.0, {bd('K')}.1).0 * N",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],f"<f64 as RealScalar>::sbmv(l, Uplo::Upper, N, K, 1.0, {{a}}, m(l, {bd('K')}.0, {bd('K')}.1).0, {{x}}, 2, 0.5, {{y}}, 2)")
S("spmv",R,"RealScalar",[("ap","p(N)",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],"<f64 as RealScalar>::spmv(l, Uplo::Upper, N, 1.0, {ap}, {x}, 2, 0.5, {y}, 2)")
S("spr",R,"RealScalar",[("x","v(N, 2)",False),("ap","p(N)",True)],"<f64 as RealScalar>::spr(l, Uplo::Upper, N, 1.0, {x}, 2, {ap})")
S("spr2",R,"RealScalar",[("x","v(N, 2)",False),("y","v(N, 2)",False),("ap","p(N)",True)],"<f64 as RealScalar>::spr2(l, Uplo::Upper, N, 1.0, {x}, 2, {y}, 2, {ap})")
# complex-only (Complex64)
one="Complex64::new(1.0, 0.0)"; half="Complex64::new(0.5, 0.0)"
S("hemv",C,"ComplexScalar",[("a","m(l, N, N).1",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],f"<Complex64 as ComplexScalar>::hemv(l, Uplo::Upper, N, {one}, {{a}}, m(l, N, N).0, {{x}}, 2, {half}, {{y}}, 2)")
S("her",C,"ComplexScalar",[("x","v(N, 2)",False),("a","m(l, N, N).1",True)],"<Complex64 as ComplexScalar>::her(l, Uplo::Upper, N, 1.0, {x}, 2, {a}, m(l, N, N).0)")
S("her2",C,"ComplexScalar",[("x","v(N, 2)",False),("y","v(N, 2)",False),("a","m(l, N, N).1",True)],f"<Complex64 as ComplexScalar>::her2(l, Uplo::Upper, N, {one}, {{x}}, 2, {{y}}, 2, {{a}}, m(l, N, N).0)")
S("geru",C,"ComplexScalar",[("x","v(M, 2)",False),("y","v(N, 2)",False),("a","m(l, M, N).1",True)],f"<Complex64 as ComplexScalar>::geru(l, M, N, {one}, {{x}}, 2, {{y}}, 2, {{a}}, m(l, M, N).0)")
S("gerc",C,"ComplexScalar",[("x","v(M, 2)",False),("y","v(N, 2)",False),("a","m(l, M, N).1",True)],f"<Complex64 as ComplexScalar>::gerc(l, M, N, {one}, {{x}}, 2, {{y}}, 2, {{a}}, m(l, M, N).0)")
S("hemm",C,"ComplexScalar",[("a","m(l, M, M).1",False),("b","m(l, M, N).1",False),("c","m(l, M, N).1",True)],f"<Complex64 as ComplexScalar>::hemm(l, Side::Left, Uplo::Upper, M, N, {one}, {{a}}, m(l, M, M).0, {{b}}, m(l, M, N).0, {half}, {{c}}, m(l, M, N).0)")
S("herk",C,"ComplexScalar",[("a","m(l, N, K).1",False),("c","m(l, N, N).1",True)],"<Complex64 as ComplexScalar>::herk(l, Uplo::Upper, Trans::No, N, K, 1.0, {a}, m(l, N, K).0, 0.5, {c}, m(l, N, N).0)")
S("her2k",C,"ComplexScalar",[("a","m(l, N, K).1",False),("b","m(l, N, K).1",False),("c","m(l, N, N).1",True)],f"<Complex64 as ComplexScalar>::her2k(l, Uplo::Upper, Trans::No, N, K, {one}, {{a}}, m(l, N, K).0, {{b}}, m(l, N, K).0, 0.5, {{c}}, m(l, N, N).0)")
S("hbmv",C,"ComplexScalar",[("a",f"m(l, {bd('K')}.0, {bd('K')}.1).0 * N",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],f"<Complex64 as ComplexScalar>::hbmv(l, Uplo::Upper, N, K, {one}, {{a}}, m(l, {bd('K')}.0, {bd('K')}.1).0, {{x}}, 2, {half}, {{y}}, 2)")
S("hpmv",C,"ComplexScalar",[("ap","p(N)",False),("x","v(N, 2)",False),("y","v(N, 2)",True)],f"<Complex64 as ComplexScalar>::hpmv(l, Uplo::Upper, N, {one}, {{ap}}, {{x}}, 2, {half}, {{y}}, 2)")
S("hpr",C,"ComplexScalar",[("x","v(N, 2)",False),("ap","p(N)",True)],"<Complex64 as ComplexScalar>::hpr(l, Uplo::Upper, N, 1.0, {x}, 2, {ap})")
S("hpr2",C,"ComplexScalar",[("x","v(N, 2)",False),("y","v(N, 2)",False),("ap","p(N)",True)],f"<Complex64 as ComplexScalar>::hpr2(l, Uplo::Upper, N, {one}, {{x}}, 2, {{y}}, 2, {{ap}})")
out=HEAD
out+='''macro_rules! case {
    ($name:ident, $body:expr) => {
        #[test]
        fn $name() {
            let r = $body.map(|_| ());
            assert!(matches!(r, Err(aocl_error::Error::InvalidArgument(_))), "{}: {:?}", stringify!($name), r);
        }
    };
}
/// Level-1 two-vector calls take `n` from the shorter vector, so a one-element-short vector just means one fewer element: no fault, either result.
macro_rules! tolerated {
    ($name:ident, $body:expr) => {
        #[test]
        fn $name() {
            let _ = $body.map(|_| ());
        }
    };
}
macro_rules! control {
    ($name:ident, $body:expr) => {
        #[test]
        fn $name() {
            $body.unwrap();
        }
    };
}
'''
for name,ty,trait,slices,call,layout in specs:
    elem="1.0f64" if ty==R else "Complex64::new(1.0, 0.0)"
    for lname in (["rm","cm"] if layout else [""]):
        lval={"rm":"Layout::RowMajor","cm":"Layout::ColMajor","":"Layout::RowMajor"}[lname]
        tag=f"{name}_{ty.lower()}"+(f"_{lname}" if lname else "")
        def vec(sz): return f"vec![{elem}; {sz}]"
        def build(short):
            lets=""
            args={}
            for key,sz,mut in slices:
                if key==short: continue
                lets+=f"let mut {key}v = {vec(sz)}; "
                args[key]=("&mut " if mut else "&")+f"{key}v"
            if short:
                sz=[s for k,s,_ in slices if k==short][0]
                args[short]=short
                body=call.format(**args)
                return f"{{ let l = {lval}; {lets}at_guard(&{vec(sz)}, {sz} - 1, |{short}| {body}) }}"
            body=call.format(**args)
            return f"{{ let l = {lval}; {lets}{body} }}"
        out+=f"control!({tag}_control, {build(None)});\n"
        for key,sz,mut in slices:
            out+=("case" if layout else "tolerated")+f"!({tag}_short_{key}, {build(key)});\n"
open(sys.argv[1],"w",encoding="utf8").write(out)
print(len([1 for s in specs]),"specs")
